export const curricula=[
 {id:'flourish',title:'Flourish Fellowship',theme:'#a95236',audience:'People building ventures rooted in community.',overview:'Flourish brings an entrepreneur’s idea into conversation with customers, community, and the practical choices required to grow.',chapters:['Begin with the community','Understand the people you serve','Test a useful offer','Build a sustainable practice'],sample:'A venture begins with attention. Before naming a solution, spend time with the people who live with the problem. Ask what they already do, what they wish were easier, and what resources they trust. Write down the patterns you hear without trying to turn every conversation into a sale. The first useful exercise is a listening map: name three groups your work could serve, the questions you need to ask each group, and one assumption you are willing to change. Your goal is to leave with a better question, not a finished pitch.'},
 {id:'ai',title:'AI',theme:'#254963',audience:'Builders who want to use AI with purpose and care.',overview:'An approachable curriculum for recognizing where AI can help a team think, create, and work while keeping human judgment in charge.',chapters:['Choose the right problem','Understand the tool','Design a human review','Measure what changed'],sample:'Start with a task rather than a tool. Find a repeated piece of work that takes time and has a clear standard for a good result. Describe the work as it happens today, then identify the step where an AI assistant might help. Decide in advance who checks the output and what information should never be entered into the system. A small pilot should produce evidence: time saved, quality improved, or a reason to stop. The point is to strengthen people’s work, not to automate a process you have not understood.'},
 {id:'blockchain',title:'Blockchain',theme:'#686039',audience:'Community leaders exploring shared records and ownership.',overview:'A plain-language introduction to shared ledgers, digital ownership, and the situations where those tools may or may not serve a community.',chapters:['What a shared ledger does','Trust and governance','Ownership in practice','Evaluate a real use case'],sample:'A blockchain is a way for several participants to maintain a shared record without relying on one party to rewrite it alone. That feature can be useful when the record crosses organizations and no single operator should control it. It also adds complexity. Begin by drawing the people and institutions who need to agree on a fact. Ask who can add information, who can correct mistakes, and who is accountable when the record is wrong. If those questions do not have good answers, technology will not settle them for you.'},
 {id:'cooperatives',title:'Cooperatives',theme:'#806044',comingSoon:true,overview:'A future guide to shared ownership, democratic decisions, and building enterprises together.'},
 {id:'finance',title:'Finance',theme:'#516449',comingSoon:true,overview:'A future guide to understanding the numbers that shape a venture and its choices.'},
 {id:'funds',title:'Funds',theme:'#544b68',comingSoon:true,overview:'A future guide to designing pools of capital around a clear purpose and community.'}
];
export const curriculumById=Object.fromEntries(curricula.map(item=>[item.id,item]));
